// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller) public {
        // Restrict to callers that have not been approved
        vm.assume(!c.approvedLoggers(_caller));
        // The reference C should return false for unapproved callers
        bool result = c.approvedToLog(_caller);
        assertTrue(!result);
    }
}

